# Helm rollback: history is append-only; rollback copies an old revision into a new one
history = []  # each item: (revision, manifest, status)

def release(manifest):
    rev = len(history) + 1  # revision numbers only grow
    for i, (r, m, s) in enumerate(history):
        if s == "deployed":
            history[i] = (r, m, "superseded")
    history.append((rev, manifest, "deployed"))

def rollback(to_rev):
    old = history[to_rev - 1][1]
    release(old)  # re-apply old manifest as a NEW revision, nothing deleted

for v in range(1, 9):
    release("image:v%d" % v)
print("before:", history[-1])
rollback(7)
for h in history[-3:]:
    print(h)
print("revisions kept:", len(history))  # 9, not 7

# Helm values: maps merge key by key, lists are replaced, null deletes a key
def merge(base, over):
    out = dict(base)
    for k, v in over.items():
        if v is None:
            out.pop(k, None)  # null removes the default key
        elif isinstance(v, dict) and isinstance(out.get(k), dict):
            out[k] = merge(out[k], v)  # maps: recurse
        else:
            out[k] = v  # lists and scalars: replace as a whole
    return out

defaults = {"replicas": 2, "image": {"repo": "web", "tag": "1.0"},
            "hosts": ["a.example", "b.example"], "debug": True}
prod = {"image": {"tag": "2.0"}, "hosts": ["c.example"], "debug": None}
print("defaults:", defaults)
print("override:", prod)
print("result  :", merge(defaults, prod))
# image.repo kept, hosts replaced (not appended), debug removed
